"""Contact sheet for substitute teachers."""

from rosterkit.errors import ProjectError


def _check(students):
    if not students:
        raise ProjectError("no students given")
    for stud in students:
        if not stud.email:
            raise ProjectError(
                f"no email for {stud.display_name}"
            )


def _name(stud):
    return stud.display_name


def _cells(stud):
    return (stud.display_name, stud.section, stud.email)


def _wide(column):
    return max(len(cell) for cell in column)


def _line(row, widths):
    text = "  ".join(map(str.ljust, row, widths))
    return text.rstrip()


# ---
def contact_rows(students):
    _check(students)
    ordered = sorted(students, key=_name)
    cells = [_cells(stud) for stud in ordered]
    widths = [_wide(column) for column in zip(*cells)]
    return [_line(row, widths) for row in cells]

